// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("POST "+options.BaseURL+"/api/addresses", wrapper.CreateAddress)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/addresses/{id}", wrapper.DeleteAddress)
	m.HandleFunc("GET "+options.BaseURL+"/api/addresses/{id}", wrapper.GetAddress)
	m.HandleFunc("PUT "+options.BaseURL+"/api/addresses/{id}", wrapper.UpdateAddress)
	m.HandleFunc("GET "+options.BaseURL+"/api/config", wrapper.GetConfig)
	m.HandleFunc("GET "+options.BaseURL+"/api/people", wrapper.ListPeople)
	m.HandleFunc("POST "+options.BaseURL+"/api/people", wrapper.CreatePerson)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/people/{id}", wrapper.DeletePerson)
	m.HandleFunc("GET "+options.BaseURL+"/api/people/{id}", wrapper.GetPerson)
	m.HandleFunc("PUT "+options.BaseURL+"/api/people/{id}", wrapper.UpdatePerson)
	m.HandleFunc("POST "+options.BaseURL+"/api/people/{id}/contact-methods", wrapper.CreateContactMethod)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/people/{id}/contact-methods/{method_id}", wrapper.DeleteContactMethod)
	m.HandleFunc("GET "+options.BaseURL+"/api/people/{id}/interactions", wrapper.ListInteractions)
	m.HandleFunc("POST "+options.BaseURL+"/api/people/{id}/interactions", wrapper.CreateInteraction)
	m.HandleFunc("POST "+options.BaseURL+"/api/pets", wrapper.CreatePet)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/pets/{id}", wrapper.DeletePet)
	m.HandleFunc("GET "+options.BaseURL+"/api/pets/{id}", wrapper.GetPet)
	m.HandleFunc("PUT "+options.BaseURL+"/api/pets/{id}", wrapper.UpdatePet)
	m.HandleFunc("POST "+options.BaseURL+"/api/relationships", wrapper.CreateRelationship)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/relationships/{id}", wrapper.DeleteRelationship)
	m.HandleFunc("POST "+options.BaseURL+"/api/work", wrapper.CreateWork)
	m.HandleFunc("DELETE "+options.BaseURL+"/api/work/{id}", wrapper.DeleteWork)
	m.HandleFunc("GET "+options.BaseURL+"/api/work/{id}", wrapper.GetWork)
	m.HandleFunc("PUT "+options.BaseURL+"/api/work/{id}", wrapper.UpdateWork)

	return m
}

