// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Create a new address with an embedded location
	// (POST /api/addresses)
	CreateAddress(ctx context.Context, request CreateAddressRequestObject) (CreateAddressResponseObject, error)
	// Delete an address
	// (DELETE /api/addresses/{id})
	DeleteAddress(ctx context.Context, request DeleteAddressRequestObject) (DeleteAddressResponseObject, error)
	// Get an address
	// (GET /api/addresses/{id})
	GetAddress(ctx context.Context, request GetAddressRequestObject) (GetAddressResponseObject, error)
	// Update an address and its location
	// (PUT /api/addresses/{id})
	UpdateAddress(ctx context.Context, request UpdateAddressRequestObject) (UpdateAddressResponseObject, error)
	// Return a safe (redacted) view of the running config
	// (GET /api/config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// List all people, optionally filtered by name/nickname substring
	// (GET /api/people)
	ListPeople(ctx context.Context, request ListPeopleRequestObject) (ListPeopleResponseObject, error)
	// Create a new person
	// (POST /api/people)
	CreatePerson(ctx context.Context, request CreatePersonRequestObject) (CreatePersonResponseObject, error)
	// Delete a person and all cascade-related data
	// (DELETE /api/people/{id})
	DeletePerson(ctx context.Context, request DeletePersonRequestObject) (DeletePersonResponseObject, error)
	// Get a person with all linked data
	// (GET /api/people/{id})
	GetPerson(ctx context.Context, request GetPersonRequestObject) (GetPersonResponseObject, error)
	// Update a person's core fields
	// (PUT /api/people/{id})
	UpdatePerson(ctx context.Context, request UpdatePersonRequestObject) (UpdatePersonResponseObject, error)
	// Add a contact method to a person
	// (POST /api/people/{id}/contact-methods)
	CreateContactMethod(ctx context.Context, request CreateContactMethodRequestObject) (CreateContactMethodResponseObject, error)
	// Remove a contact method
	// (DELETE /api/people/{id}/contact-methods/{method_id})
	DeleteContactMethod(ctx context.Context, request DeleteContactMethodRequestObject) (DeleteContactMethodResponseObject, error)
	// List interactions for a person, newest first
	// (GET /api/people/{id}/interactions)
	ListInteractions(ctx context.Context, request ListInteractionsRequestObject) (ListInteractionsResponseObject, error)
	// Log a new interaction with a person
	// (POST /api/people/{id}/interactions)
	CreateInteraction(ctx context.Context, request CreateInteractionRequestObject) (CreateInteractionResponseObject, error)
	// Create a new pet
	// (POST /api/pets)
	CreatePet(ctx context.Context, request CreatePetRequestObject) (CreatePetResponseObject, error)
	// Delete a pet
	// (DELETE /api/pets/{id})
	DeletePet(ctx context.Context, request DeletePetRequestObject) (DeletePetResponseObject, error)
	// Get a pet
	// (GET /api/pets/{id})
	GetPet(ctx context.Context, request GetPetRequestObject) (GetPetResponseObject, error)
	// Update a pet
	// (PUT /api/pets/{id})
	UpdatePet(ctx context.Context, request UpdatePetRequestObject) (UpdatePetResponseObject, error)
	// Create a relationship from a person to another entity
	// (POST /api/relationships)
	CreateRelationship(ctx context.Context, request CreateRelationshipRequestObject) (CreateRelationshipResponseObject, error)
	// Remove a relationship
	// (DELETE /api/relationships/{id})
	DeleteRelationship(ctx context.Context, request DeleteRelationshipRequestObject) (DeleteRelationshipResponseObject, error)
	// Create a new work/organisation
	// (POST /api/work)
	CreateWork(ctx context.Context, request CreateWorkRequestObject) (CreateWorkResponseObject, error)
	// Delete a work/organisation
	// (DELETE /api/work/{id})
	DeleteWork(ctx context.Context, request DeleteWorkRequestObject) (DeleteWorkResponseObject, error)
	// Get a work/organisation
	// (GET /api/work/{id})
	GetWork(ctx context.Context, request GetWorkRequestObject) (GetWorkResponseObject, error)
	// Update a work/organisation
	// (PUT /api/work/{id})
	UpdateWork(ctx context.Context, request UpdateWorkRequestObject) (UpdateWorkResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

